From 65d80b754950830c2396ee23b7b5177ae9239ef9 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:33:31 +0100
Subject: [PATCH] applets/quicklaunch: fill the panel thickness with launcher
 icons

In panels each launcher icon was inset by a small padding on all sides,
so at some thicknesses it dropped to a smaller icon size than the Icon
widget next to it. Fill the thickness and space launchers lengthwise.

BUG: 461638
---
 applets/quicklaunch/IconItem.qml | 2 +-
 applets/quicklaunch/layout.js    | 4 ++--
 2 files changed, 3 insertions(+), 3 deletions(-)

diff --git a/applets/quicklaunch/IconItem.qml b/applets/quicklaunch/IconItem.qml
index ab6d8aba3..64c982d8f 100644
--- a/applets/quicklaunch/IconItem.qml
+++ b/applets/quicklaunch/IconItem.qml
@@ -175,7 +175,7 @@ Item {
         MouseArea {
             id: mouseArea
             anchors.fill: parent
-            anchors.margins: LayoutManager.itemPadding()
+            anchors.margins: iconItem.isPopupItem || Plasmoid.formFactor === PlasmaCore.Types.Planar ? LayoutManager.itemPadding() : 0
             hoverEnabled: true
             acceptedButtons: Qt.LeftButton | Qt.RightButton

diff --git a/applets/quicklaunch/layout.js b/applets/quicklaunch/layout.js
index b4fe49ed0..ece601ef6 100644
--- a/applets/quicklaunch/layout.js
+++ b/applets/quicklaunch/layout.js
@@ -53,7 +53,7 @@ function preferredWidth()
     // orientation due to binding order. Avoid infinite regression,
     // we get the correct value when the bindings settle
     if (horizontal && !vertical) {
-        w = (preferredHeight() / rows()) * cols();
+        w = (preferredHeight() / rows() + 2 * itemPadding()) * cols();
     }
     if (!vertical && popupArrow.visible) {
         w += popupArrow.width;
@@ -65,7 +65,7 @@ function preferredHeight()
 {
     var h = rows() * preferredCellHeight();
     if (vertical && !horizontal) {
-        h = (preferredWidth() / cols()) * rows();
+        h = (preferredWidth() / cols() + 2 * itemPadding()) * rows();
         if (popupArrow.visible) {
             h += popupArrow.height;
         }
-- 
